-- PLAN-0035: Ad Stacks, canonical geography, ad types, and legacy backfill.
-- Generated by scripts/generate-plan0035-geo-seed.cjs from the vendored ISO datasets.
-- Do not hand-edit the seed rows; update the datasets and regenerate instead.

CREATE TABLE IF NOT EXISTS "ads_creative_stacks" (
  "id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL,
  "campaign_id" uuid NOT NULL,
  "name" varchar(100) NOT NULL,
  "position" integer NOT NULL,
  "geo_mode" varchar(16) DEFAULT 'inherit' NOT NULL,
  "target_devices" text,
  "target_hours" text,
  "created_at" timestamp with time zone DEFAULT now() NOT NULL,
  "updated_at" timestamp with time zone DEFAULT now() NOT NULL
);
ALTER TABLE "ads_creative_stacks" DROP CONSTRAINT IF EXISTS "ads_creative_stacks_campaign_id_ads_campaigns_id_fk";
ALTER TABLE "ads_creative_stacks" ADD CONSTRAINT "ads_creative_stacks_campaign_id_ads_campaigns_id_fk" FOREIGN KEY ("campaign_id") REFERENCES "ads_campaigns"("id") ON DELETE cascade;
CREATE UNIQUE INDEX IF NOT EXISTS "ads_creative_stacks_campaign_position_uq" ON "ads_creative_stacks" ("campaign_id","position");
CREATE INDEX IF NOT EXISTS "ads_creative_stacks_campaign_id_idx" ON "ads_creative_stacks" ("campaign_id");

CREATE TABLE IF NOT EXISTS "crimfig_geo_places" (
  "id" varchar(160) PRIMARY KEY NOT NULL,
  "scope" varchar(16) NOT NULL,
  "parent_id" varchar(160),
  "name" text NOT NULL,
  "normalized_name" text NOT NULL,
  "country_code" varchar(2),
  "subdivision_code" varchar(16),
  "latitude" double precision,
  "longitude" double precision,
  "geo_version" varchar(40) NOT NULL,
  "source_provider" varchar(20),
  "source_place_id" text,
  "created_at" timestamp with time zone DEFAULT now() NOT NULL
);
CREATE INDEX IF NOT EXISTS "crimfig_geo_places_scope_idx" ON "crimfig_geo_places" ("scope");
CREATE INDEX IF NOT EXISTS "crimfig_geo_places_parent_idx" ON "crimfig_geo_places" ("parent_id");
CREATE INDEX IF NOT EXISTS "crimfig_geo_places_country_idx" ON "crimfig_geo_places" ("country_code");
CREATE UNIQUE INDEX IF NOT EXISTS "crimfig_geo_places_city_name_uq" ON "crimfig_geo_places" ("parent_id","normalized_name","geo_version") WHERE scope = 'city';

CREATE TABLE IF NOT EXISTS "crimfig_geo_targets" (
  "id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL,
  "owner_type" varchar(16) NOT NULL,
  "owner_id" uuid NOT NULL,
  "place_id" varchar(160) NOT NULL,
  "scope" varchar(16) NOT NULL,
  "geo_version" varchar(40) NOT NULL,
  "resolved_countries" text DEFAULT '[]' NOT NULL,
  "resolved_subdivisions" text DEFAULT '[]' NOT NULL,
  "resolved_cities" text DEFAULT '[]' NOT NULL,
  "created_at" timestamp with time zone DEFAULT now() NOT NULL
);
CREATE UNIQUE INDEX IF NOT EXISTS "crimfig_geo_targets_owner_place_uq" ON "crimfig_geo_targets" ("owner_type","owner_id","place_id");
CREATE INDEX IF NOT EXISTS "crimfig_geo_targets_owner_idx" ON "crimfig_geo_targets" ("owner_type","owner_id");

DO $$ BEGIN
  CREATE TYPE "public"."ads_creative_ad_type" AS ENUM ('text','image','video');
EXCEPTION WHEN duplicate_object THEN NULL; END $$;

ALTER TABLE "ads_campaigns" ADD COLUMN IF NOT EXISTS "geo_mode" varchar(16) DEFAULT 'global' NOT NULL;
ALTER TABLE "ads_campaigns" ADD COLUMN IF NOT EXISTS "category" varchar(80);
ALTER TABLE "ads_campaigns" ADD COLUMN IF NOT EXISTS "channels" text;
ALTER TABLE "ads_campaigns" ADD COLUMN IF NOT EXISTS "is_bonus_delivery" boolean DEFAULT false NOT NULL;

ALTER TABLE "ads_creatives" ADD COLUMN IF NOT EXISTS "ad_stack_id" uuid;
ALTER TABLE "ads_creatives" ADD COLUMN IF NOT EXISTS "ad_type" "public"."ads_creative_ad_type" DEFAULT 'text' NOT NULL;
ALTER TABLE "ads_creatives" ADD COLUMN IF NOT EXISTS "poster_url" text;

-- One default stack per existing campaign, then assign every existing creative.
SELECT c.id, 'Ad Stack #1', 1 FROM "ads_campaigns" c
WHERE NOT EXISTS (SELECT 1 FROM "ads_creative_stacks" s WHERE s.campaign_id = c.id);
UPDATE "ads_creatives" cr SET "ad_stack_id" = s.id
FROM "ads_creative_stacks" s
WHERE s.campaign_id = cr.campaign_id AND s.position = 1 AND cr.ad_stack_id IS NULL;
ALTER TABLE "ads_creatives" ALTER COLUMN "ad_stack_id" SET NOT NULL;
ALTER TABLE "ads_creatives" DROP CONSTRAINT IF EXISTS "ads_creatives_ad_stack_id_ads_creative_stacks_id_fk";
ALTER TABLE "ads_creatives" ADD CONSTRAINT "ads_creatives_ad_stack_id_ads_creative_stacks_id_fk" FOREIGN KEY ("ad_stack_id") REFERENCES "ads_creative_stacks"("id") ON DELETE restrict;
CREATE INDEX IF NOT EXISTS "ads_creatives_stack_id_idx" ON "ads_creatives" ("ad_stack_id");

-- Derive legacy ad type from real asset references. Ambiguous rows default to text and are reported by the validation script.
UPDATE "ads_creatives" SET "ad_type" = 'video' WHERE "video_url" IS NOT NULL AND "video_url" <> '';
UPDATE "ads_creatives" SET "ad_type" = 'image' WHERE ("video_url" IS NULL OR "video_url" = '') AND "image_url" IS NOT NULL AND "image_url" <> '';

-- Explicitly mark campaigns that already carried country/state targeting, then map
-- recognizable countries. Unmatched legacy values remain readable in the old columns.
UPDATE "ads_campaigns" SET "geo_mode" = 'targeted'
WHERE ("target_countries" IS NOT NULL AND "target_countries" <> '[]')
   OR ("target_states" IS NOT NULL AND "target_states" <> '[]');

SELECT 'campaign', c.id, 'country:' || upper(cc), 'country', 'crimfig-geo-2026.10',
       jsonb_build_array(upper(cc))::text, '[]'
FROM "ads_campaigns" c
CROSS JOIN LATERAL jsonb_array_elements_text(c.target_countries::jsonb) AS cc
WHERE c.target_countries IS NOT NULL AND c.target_countries LIKE '[%'
ON CONFLICT ("owner_type","owner_id","place_id") DO NOTHING;

SELECT 'campaign', c.id, 'state:' || p.subdivision_code, 'state', 'crimfig-geo-2026.10',
       CASE WHEN p.country_code IS NULL THEN '[]' ELSE jsonb_build_array(p.country_code)::text END,
       jsonb_build_array(p.subdivision_code)::text
FROM "ads_campaigns" c
CROSS JOIN LATERAL jsonb_array_elements_text(c.target_states::jsonb) AS st
JOIN "crimfig_geo_places" p ON p.scope = 'state'
  AND p.geo_version = 'crimfig-geo-2026.10'
  AND p.normalized_name = btrim(regexp_replace(lower(st), '[^a-z0-9]+', ' ', 'g'))
  AND (c.target_countries IS NULL OR p.country_code IN (SELECT upper(x) FROM jsonb_array_elements_text(c.target_countries::jsonb) x))
WHERE c.target_states IS NOT NULL AND c.target_states LIKE '[%'
ON CONFLICT ("owner_type","owner_id","place_id") DO NOTHING;

